import express from 'express';

const AGREEMENT_PICKER_FUNCTION = Buffer.from('', 'base64').toString('utf8');
const previousSend = express.response.send;

express.response.send = function agreementGuarantorDropdownPatch(body) {
  try {
    const requestPath = this.req?.path || this.req?.url || '';
    if (typeof body === 'string' && requestPath.startsWith('/app.js')) {
      const start = body.indexOf('async function openAgreementPicker(id){');
      const end = body.indexOf('\nasync function showLoan(id){', start);
      if (start !== -1 && end !== -1) {
        body = body.slice(0, start) + AGREEMENT_PICKER_FUNCTION + body.slice(end);
      }
    }
  } catch (_) {}

  return previousSend.call(this, body);
};
